import {buildContractData,generateContract} from './contract.js';
export function initContracts({getQuote,getProject,getClient,getAddress,view,toast}){
 const $=id=>document.getElementById(id),form=$('contract-form');let loaded=false,busy=false;
 const companyKeys=['providerThai','providerChinese','providerAddressThai','providerAddressChinese','account1Name','account1Number','account1Bank','account1Branch','account2Name','account2Number','account2Bank','account2Branch'];
 const bangkokDate=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Bangkok',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
 function info(){return {projectName:getProject(),ownerName:getClient(),projectAddress:getAddress(),ownerId:$('owner-id').value,ownerAddress:$('owner-address').value,date:$('contract-date').value,depositPct:$('deposit-pct').value,filingFee:$('filing-fee').value,codDays:$('cod-days').value,...Object.fromEntries(companyKeys.map(k=>[k,$(k).value]))};}
 function summary(){const q=getQuote();$('contract-name').value=getProject()?getProject()+'光伏系统施工合同':'';$('contract-project').textContent=getProject()||'请在报价页填写项目名称';$('contract-owner').textContent=getClient()||'请在报价页填写甲方名称';$('contract-address').textContent=getAddress()||'请在报价页填写项目地址';$('contract-total').textContent=q?'THB '+q.total.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}):'请先完成有效报价';$('contract-kwp').textContent=q?`${q.kwp} kWp · 预计现场 ${q.days} 工作日`:'';try{const d=buildContractData(q,info());$('contract-payment').textContent=`首款 THB ${d.values.DEPOSIT}；尾款 THB ${d.values.BALANCE}；合计 THB ${d.values.TOTAL}`;}catch(e){$('contract-payment').textContent=e.message;}}
 async function open(){view('contracts');$('contract-status').textContent='';if(!loaded){try{const r=await fetch('contract-defaults.json');if(!r.ok)throw Error();const defaults=await r.json();let saved={};try{saved=JSON.parse(localStorage.getItem('maxing-contract-company-v1'))||{};}catch{}for(const k of companyKeys)$(k).value=saved[k]??defaults[k]??'';loaded=true;}catch{$('contract-status').textContent='无法载入公司默认资料，请手动填写。';loaded=true;}}$('owner-id').value='';$('owner-address').value=getAddress();if(!$('contract-date').value)$('contract-date').value=bangkokDate();summary();}
 form.addEventListener('input',summary);
 $('save-company').onclick=()=>{try{localStorage.setItem('maxing-contract-company-v1',JSON.stringify(Object.fromEntries(companyKeys.map(k=>[k,$(k).value]))));toast('公司与收款资料已保存在此浏览器');}catch{toast('浏览器存储不可用，请自行保留公司资料');}};
 $('contract-back').onclick=()=>view('quote');
 form.onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;$('download-contract').disabled=true;$('contract-status').textContent='正在将报价数据写入合同…';try{const q=getQuote(),details=info();buildContractData(q,details);const response=await fetch('contract-template.docx?revision=cn32-20261109');if(!response.ok)throw Error('合同模板加载失败，请刷新后重试');const result=await generateContract(await response.arrayBuffer(),q,details);const url=URL.createObjectURL(new Blob([result.bytes],{type:'application/vnd.openxmlformats-officedocument.wordprocessingml.document'}));const a=document.createElement('a');a.href=url;a.download=result.filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);$('contract-status').textContent='Word 合同已生成。项目、容量、总价及分期金额已同步；请在签署前核对内容。';toast('Word 合同已下载');}catch(err){$('contract-status').textContent=err.message;}finally{busy=false;$('download-contract').disabled=false;}};
 return {open,summary};
}